{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Viqualine, the closest structural analogue (Morgan 0.408), showed oral bioavailability of 0.73 ± 0.07 in human volunteers, directly supporting high F for the query because it shares the methoxyquinoline and vinylamine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Viqualine absolute bioavailability averaged 80% versus intravenous dosing in healthy subjects, corroborating good oral absorption for the closest analogue class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, a methoxyquinoline-containing drug, has absolute bioavailability in the order of 85% in humans, supporting that this quinoline/methoxyquinoline scaffold can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride, a basic heteroaromatic drug, showed mean apparent systemic availability of 89.7% after oral administration, supporting high F for a basic amine with an aromatic heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Tegaserod, a methoxyindole basic drug, has absolute bioavailability of about 10% under fasting conditions, providing a contradictory example that methoxyheteroaromatic basic drugs can have low F; however, its different heterocycle and lower similarity reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "D7 melatonin showed absolute bioavailability of 8.6% in male subjects, another low-F methoxyindole example, but it lacks the quinoline and bicyclic amine features and undergoes extensive first-pass metabolism, limiting relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine has high oral bioavailability (73–80%) in humans, and other methoxyquinoline/basic amine drugs such as lenvatinib and alizapride are also well absorbed. Low-F examples like tegaserod and melatonin are less structurally similar and involve different heterocycles or metabolic liabilities. Therefore the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The closest analogue, viqualine, has only moderate Morgan similarity (0.408), and the query's rigid bicyclic amine and hydroxyl substituent are not directly covered by the evidence.",
    "Fasted-state bioavailability data are not explicitly reported for viqualine or most supporting analogues.",
    "Potential first-pass metabolism or transporter-mediated efflux for the query's specific scaffold is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

